import Foundation

extension SocialSupportGuides {
    static let benefits = DirectoryGuide(
        cardSummary: .init(ukrainian: "Право на Sozialhilfe, заява, рішення та зміни доходу", german: "Sozialhilfe: Anspruch, Antrag, Bescheid und Einkommen"),
        introduction: .init(ukrainian: "Sozialhilfe/Mindestsicherung і Grundversorgung мають різні умови. Почніть зі статусу перебування та перевірте правила своєї землі.", german: "Sozialhilfe/Mindestsicherung und Grundversorgung haben unterschiedliche Voraussetzungen. Beginnen Sie mit dem Aufenthaltsstatus und den Regeln Ihres Bundeslands."),
        sections: [
            .init("status", "person.text.rectangle", "Кому доступна Sozialhilfe", "Wer Sozialhilfe erhalten kann", "Особи з тимчасовим захистом і заявники на притулок не мають права на Sozialhilfe; за потреби їм слід перевірити Grundversorgung. Визнані біженці мають право на Sozialhilfe за загальних умов. Для інших громадян третіх країн зазвичай потрібне понад п’ять років законного перебування; винятки перевіряйте індивідуально. Назва посвідки важливіша за громадянство саме по собі.", "Vertriebene und Asylwerbende haben keinen Sozialhilfeanspruch; bei Bedürftigkeit ist Grundversorgung zu prüfen. Anerkannte Flüchtlinge können Sozialhilfe nach den allgemeinen Regeln beanspruchen. Andere Drittstaatsangehörige brauchen grundsätzlich mehr als fünf Jahre rechtmäßigen Aufenthalt; Ausnahmen individuell prüfen. Entscheidend ist der genaue Aufenthaltstitel, nicht allein die Staatsangehörigkeit.", source: foreignEligibility),
            .init("need", "list.bullet.clipboard", "Що перевіряють перед рішенням", "Was vor der Entscheidung geprüft wird", "Орган перевіряє склад спільного господарства, доходи, майно, житлові витрати та можливості роботи. Розрахунок і додаткові допомоги різняться за землею. Зберіть посвідку, Meldezettel, договір оренди, виписки про доходи й заощадження; попросіть список документів саме для вашої землі.", "Die Behörde prüft Haushalt, Einkommen, Vermögen, Wohnkosten und Arbeitsmöglichkeiten. Berechnung und Zusatzleistungen unterscheiden sich nach Bundesland. Aufenthaltstitel, Meldezettel, Mietvertrag sowie Einkommens- und Vermögensnachweise sammeln; Unterlagenliste für das eigene Land verlangen.", source: social),
            .init("apply", "building.columns", "Куди подавати заяву", "Wo der Antrag gestellt wird", "Подайте заяву до Bezirksverwaltungsbehörde за місцем проживання: Gemeindeamt або Bezirkshauptmannschaft, у статутному місті Magistrat, у Відні MA 40. Перевірте точний шлях землі та попросіть підтвердження дати подання. Допомога не виникає автоматично після реєстрації місця проживання.", "Antrag bei der Bezirksverwaltungsbehörde des Wohnorts stellen: Gemeindeamt oder Bezirkshauptmannschaft, in Statutarstädten Magistrat, in Wien MA 40. Den genauen Landesweg prüfen und Eingangsdatum bestätigen lassen. Die Wohnsitzmeldung löst die Leistung nicht automatisch aus.", source: social),
            .init("decision", "doc.text", "Звірте Bescheid", "Bescheid prüfen", "Після рішення перевірте врахованих членів родини, доходи, житло, дату початку й суму. Якщо орган відмовив або сума здається помилковою, попросіть письмовий Bescheid і прочитайте вказаний у ньому строк та спосіб оскарження. Не орієнтуйтеся на усне пояснення без документа.", "Nach der Entscheidung berücksichtigte Haushaltsmitglieder, Einkommen, Wohnkosten, Beginn und Betrag prüfen. Bei Ablehnung oder möglichem Fehler schriftlichen Bescheid verlangen und die dort genannte Rechtsmittelfrist und Einbringungsstelle beachten. Nicht nur auf eine mündliche Auskunft verlassen.", source: social),
            .init("changes", "arrow.triangle.2.circlepath", "Повідомляйте про зміни", "Änderungen melden", "Нова робота, інша виплата, переїзд або зміна складу сім’ї можуть змінити розрахунок. Повідомляйте компетентний орган у передбачений строк і зберігайте підтвердження. Якщо надійшла вимога повернути кошти, попросіть розрахунок за періодами та перевірте строк оскарження.", "Neue Arbeit, weitere Leistung, Umzug oder geänderter Haushalt können die Berechnung ändern. Zuständige Stelle fristgerecht informieren und Nachweis behalten. Bei Rückforderung Berechnung nach Zeiträumen verlangen und Rechtsmittelfrist prüfen.", source: social)
        ], sources: [foreignEligibility, social]
    )
}
